package pt.realmprogression.test;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.inventory.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.CrafterBlockEntity;
import pt.realmprogression.service.*;
import pt.realmprogression.data.ProgressStore;
import pt.realmprogression.domain.ProgressLedger;
import pt.crownledger.data.TreasuryData;
import pt.crownledger.domain.Treasury;

@GameTestHolder("realmprogression") @PrefixGameTestTemplate(false)
public final class ProgressGameTests {
    @GameTest(template="research_empty",timeoutTicks=100) public static void unlockedRepeatedShiftCraftingConsumesEachRecipeOnce(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);f.funds(100);ProgressService.observe(h.getLevel().getServer());var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,4));m.slotsChanged(m.getSlot(1).container);m.clicked(0,0,ClickType.QUICK_MOVE,f.player);h.assertTrue(f.player.getInventory().countItem(FixtureMod.TOKEN.get())==4&&m.getSlot(1).getItem().isEmpty(),"Repeated native crafting duplicated outputs or left inputs");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void aWarmedAutomaticRecipeCacheCannotBypassANewLock(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){var input=CraftingInput.of(1,1,List.of(new ItemStack(Items.COBBLESTONE)));h.assertTrue(CrafterBlock.getPotentialResults(h.getLevel(),input).isPresent(),"Native cache was not warmed");f.lock(100);h.assertTrue(CrafterBlock.getPotentialResults(h.getLevel(),input).isEmpty(),"Cached crafter recipe bypassed a new rule");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void publicIncomeUnlocksBeforeLaterSpendingInTheSameTick(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var s=h.getLevel().getServer();pt.crownledger.api.CrownIncomeApi.credit(s,UUID.randomUUID(),"CHRONICLES",100,f.admin.getUUID(),"research-test-funded-income");var d=TreasuryData.get(s);d.treasury.removeFunds(Treasury.Currency.CHRONICLES,100,Treasury.Kind.CONTRACT_FUNDING,f.admin.getUUID(),"Same tick public expense",10);d.setDirty();h.assertTrue(!f.store.state().blocked("progressionfixture")&&d.treasury.balance(Treasury.Currency.CHRONICLES)==0,"A confirmed intermediate public balance was missed");}h.succeed();System.out.println("PROGRESSION_OBSERVER_PASSED");}
    @GameTest(template="research_empty",timeoutTicks=100) public static void aDurableTreasuryCommitAlsoTriggersResearch(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var s=h.getLevel().getServer();var d=TreasuryData.get(s);var next=d.treasury.copy();next.addFunds(Treasury.Currency.CHRONICLES,100,Treasury.Kind.DEPOSIT,f.admin.getUUID(),"Native durable balance",10);d.commitGovernance(s,next,d.governance.copy());h.assertTrue(!f.store.state().blocked("progressionfixture"),"Durable treasury commit was not observed");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void anUnlockStorageFailureRetainsTheLockAndDoesNotAnnounce(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var file=f.store.path();byte[] previous=java.nio.file.Files.readAllBytes(file);java.nio.file.Files.delete(file);java.nio.file.Files.createDirectory(file);try{f.funds(100);ProgressService.observe(h.getLevel().getServer());h.assertTrue(f.store.state().blocked("progressionfixture")&&f.player.announcements()==0&&TreasuryData.get(h.getLevel().getServer()).treasury.balance(Treasury.Currency.CHRONICLES)==100,"A failed progression write unlocked or changed money");}finally{java.nio.file.Files.delete(file);java.nio.file.Files.write(file,previous);}}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void clientSuppliedBalancesAndExtraFieldsAreRejected(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);var body=f.body(f.admin,100,true);body.addProperty("balance",999999999);ProgressService.action(f.admin,"configure",body.toString());h.assertTrue(!f.store.state().rules().containsKey("progressionfixture"),"Client controlled a financial field");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void aliasingAnEssentialOutputNamespaceIsRefused(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);var body=f.body(f.admin,100,true);body.addProperty("namespaces","minecraft");ProgressService.action(f.admin,"configure",body.toString());h.assertTrue(!f.store.state().rules().containsKey("progressionfixture"),"Administrator rule bypassed essential-system protection");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void addonBootsWithTheRealTreasuryAndPhysicalRecipe(GameTestHelper h){h.assertTrue(net.neoforged.fml.ModList.get().isLoaded("kingdomtreasury")&&h.getLevel().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("realmprogression:research_table")).isPresent(),"Treasury or research table recipe missing");h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void normalPlayerCanReadButCannotConfigure(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.player);var state=f.store.state();ProgressService.action(f.player,"configure",f.body(f.player,100,true).toString());h.assertTrue(f.store.state().equals(state),"Non-OP configured a goal");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void administratorCanSelectAnotherInstalledMod(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);ProgressService.action(f.admin,"configure",f.body(f.admin,12345,true).toString());h.assertTrue(f.store.state().blocked("progressionfixture")&&f.store.state().rules().get("progressionfixture").goal()==12345,"Native administrator configuration failed");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void inventoryCraftingDoesNotProduceOrConsumeLockedItems(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,4));m.slotsChanged(m.getSlot(1).container);h.assertTrue(m.getSlot(0).getItem().isEmpty()&&m.getSlot(1).getItem().getCount()==4,"Inventory recipe bypassed the lock or consumed inputs");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void craftingTableAlsoBlocksAlternativeDatapackRecipeIds(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var m=new CraftingMenu(20,f.player.getInventory(),ContainerLevelAccess.create(h.getLevel(),f.pos));f.player.containerMenu=m;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,3));m.slotsChanged(m.getSlot(1).container);h.assertTrue(m.getSlot(0).getItem().isEmpty()&&h.getLevel().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("minecraft:research_alternative")).isPresent(),"An alternative recipe namespace bypassed output gating");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void shiftClickCannotTakeAPreviouslyCachedLockedResult(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,4));m.slotsChanged(m.getSlot(1).container);h.assertTrue(!m.getSlot(0).getItem().isEmpty(),"Native unlocked recipe not assembled");f.lock(100);var result=m.quickMoveStack(f.player,0);h.assertTrue(result.isEmpty()&&f.player.getInventory().countItem(FixtureMod.TOKEN.get())==0&&m.getSlot(1).getItem().getCount()==4,"Cached shift-click result bypassed the new lock");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void normalClickCannotRemoveAPreviouslyCachedLockedResult(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,2));m.slotsChanged(m.getSlot(1).container);f.lock(100);h.assertTrue(!m.getSlot(0).mayPickup(f.player)&&m.getSlot(0).remove(1).isEmpty()&&m.getSlot(1).getItem().getCount()==2,"Normal pickup/remove bypassed a new lock");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void vanillaCrafterDoesNotConsumeOrEjectLockedItems(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var pos=f.pos.offset(2,0,0);h.getLevel().removeBlock(pos,false);h.getLevel().setBlock(pos,Blocks.CRAFTER.defaultBlockState(),3);var tile=(CrafterBlockEntity)h.getLevel().getBlockEntity(pos);tile.setItem(0,new ItemStack(Items.COBBLESTONE,3));var method=CrafterBlock.class.getDeclaredMethod("dispenseFrom",net.minecraft.world.level.block.state.BlockState.class,net.minecraft.server.level.ServerLevel.class,BlockPos.class);method.setAccessible(true);method.invoke(Blocks.CRAFTER,h.getLevel().getBlockState(pos),h.getLevel(),pos);h.assertTrue(tile.getItem(0).getCount()==3&&CrafterBlock.getPotentialResults(h.getLevel(),tile.asCraftInput()).isEmpty(),"Native automatic crafter bypassed the lock");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void exactTreasuryGoalUnlocksWithoutSpendingMoney(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);f.funds(100);ProgressService.observe(h.getLevel().getServer());h.assertTrue(!f.store.state().blocked("progressionfixture")&&TreasuryData.get(h.getLevel().getServer()).treasury.balance(Treasury.Currency.CHRONICLES)==100,"Unlock changed the treasury balance");h.assertTrue(new ProgressStore(f.store.path()).state().equals(f.store.state()),"Unlock was announced before durable storage");}h.succeed();System.out.println("PROGRESSION_FUNDS_PASSED");}
    @GameTest(template="research_empty",timeoutTicks=100) public static void emeraldsDoNotCountAsEuroFunds(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var d=TreasuryData.get(h.getLevel().getServer());d.treasury.addFunds(Treasury.Currency.EMERALD,100000,Treasury.Kind.DEPOSIT,f.admin.getUUID(),"QA emeralds",10);d.setDirty();ProgressService.observe(h.getLevel().getServer());h.assertTrue(f.store.state().blocked("progressionfixture"),"Emeralds satisfied a euro goal");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void completedGoalOnlyAnnouncesOnce(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);f.funds(100);ProgressService.observe(h.getLevel().getServer());ProgressService.observe(h.getLevel().getServer());h.assertTrue(f.player.announcements()==1&&f.admin.announcements()==1,"An unlock notification repeated");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void unlockReopensCraftingAndPersistsAfterTreasurySpending(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);f.funds(100);ProgressService.observe(h.getLevel().getServer());f.funds(0);var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.COBBLESTONE,2));m.slotsChanged(m.getSlot(1).container);h.assertTrue(m.getSlot(0).getItem().is(FixtureMod.TOKEN.get())&&!new ProgressStore(f.store.path()).state().blocked("progressionfixture"),"Spending revoked crafting or persistence");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void replayingAnAdministrativePacketDoesNotChangeTheAuditTwice(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);var body=f.body(f.admin,100,true);ProgressService.action(f.admin,"configure",body.toString());long revision=f.store.state().revision();f.releaseLimit(f.admin);ProgressService.action(f.admin,"configure",body.toString());h.assertTrue(f.store.state().revision()==revision,"Replayed administrative packet mutated the ledger");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void revokedOperatorPermissionsApplyToExistingSessions(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);var body=f.body(f.admin,100,true);h.getLevel().getServer().getPlayerList().getOps().remove(f.admin.getGameProfile());ProgressService.action(f.admin,"configure",body.toString());h.assertTrue(!f.store.state().rules().containsKey("progressionfixture"),"Revoked administrator retained authority");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void breakingTheTableInvalidatesAdministrativeRequests(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);var body=f.body(f.admin,100,true);h.getLevel().removeBlock(f.pos,false);ProgressService.action(f.admin,"configure",body.toString());h.assertTrue(!f.store.state().rules().containsKey("progressionfixture"),"Broken table retained an active configuration session");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void existingItemsRemainUsableRatherThanBeingConfiscated(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);f.player.getInventory().setItem(0,new ItemStack(FixtureMod.TOKEN.get(),12));ProgressService.observe(h.getLevel().getServer());h.assertTrue(f.player.getInventory().getItem(0).getCount()==12,"Crafting lock confiscated existing items");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void vanillaCraftingRemainsAvailable(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.lock(100);var m=f.player.inventoryMenu;m.getSlot(1).set(new ItemStack(Items.OAK_LOG));m.slotsChanged(m.getSlot(1).container);h.assertTrue(m.getSlot(0).getItem().is(Items.OAK_PLANKS),"Lock changed unrelated Vanilla recipes");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void malformedGoalRequestsNeverChangeWorldRules(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){f.open(f.admin);for(String amount:List.of("-1","0","1.2","\"100\"","999999999999999999999999")){f.releaseLimit(f.admin);var b=f.body(f.admin,100,true);b.add("goal",com.google.gson.JsonParser.parseString(amount));ProgressService.action(f.admin,"configure",b.toString());}h.assertTrue(!f.store.state().rules().containsKey("progressionfixture"),"Malformed goal mutated world rules");}h.succeed();}
    @GameTest(template="research_empty",timeoutTicks=100) public static void realCreateCraftsAreGuardedWhenCreateIsInstalled(GameTestHelper h)throws Exception{try(var f=new ProgressFixture(h)){if(net.neoforged.fml.ModList.get().isLoaded("create")){var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("create:andesite_alloy"));h.assertTrue(item!=Items.AIR&&CraftGate.blocked(h.getLevel(),new ItemStack(item)),"Real Create output not protected by its default goal");var recipes=ModCatalog.coverage(h.getLevel().getServer());h.assertTrue(recipes.getOrDefault("create",0)>20,"Real Create standard crafting catalogue absent");System.out.println("PROGRESSION_CREATE_PASSED "+net.neoforged.fml.ModList.get().getModContainerById("create").orElseThrow().getModInfo().getVersion());}}h.succeed();}
}
